{
  "environment": {
    "container_type": "<pod|container|host>",
    "namespace": "<namespace or unknown>",
    "service_account": "<sa name or unknown>",
    "os": "<os description>",
    "is_root": true|false
  },
  "credentials": {
    "has_sa_token": true|false,
    "token_subject": "<subject if decodable>"
  },
  "permissions": {
    "source": "<how you determined this, e.g. selfsubjectrulesreview>",
    "resource_rules": [
      {"apiGroups": ["..."], "resources": ["..."], "verbs": ["..."]}
    ]
  },
  "tools": {
    "available": ["wget", "..."],
    "unavailable": ["curl", "kubectl", "..."]
  },
  "api": {
    "reachable": true|false,
    "endpoint": "<url>"
  }
}

{
  "current_permissions": [
    "create:selfsubjectaccessreviews",
    "create:selfsubjectrulesreviews",
    "create:selfsubjectreviews",
    "get:clustertrustbundles",
    "list:clustertrustbundles",
    "watch:clustertrustbundles",
    "create:pods"
  ],
  "relevant_relations": [
    {
      "from": "create:pods",
      "to": "get:secrets",
      "why_relevant": "Verified critical edge: a pod spec can mount/read secrets via serviceaccount token or hostPath, giving secret read without direct RBAC."
    },
    {
      "from": "create:pods",
      "to": "get:serviceaccounts",
      "why_relevant": "Verified medium edge: pod creation lets us enumerate/impersonate SA tokens mounted into pods, enabling privilege pivot."
    },
    {
      "from": "create:pods",
      "to": "get:configmaps",
      "why_relevant": "Verified medium edge: configmaps often hold credentials/tokens; pod can mount them."
    },
    {
      "from": "create:pods",
      "to": "get:nodes",
      "why_relevant": "Verified medium edge: pod scheduling reveals node info useful for hostPath/privileged escape planning."
    },
    {
      "from": "create:pods",
      "to": "get:persistentvolumeclaims",
      "why_relevant": "Verified medium edge: PVCs may expose other workloads' data via mounted volumes."
    }
  ],
  "directions": [
    {
      "id": "D1",
      "goal": "Confirm pod-creation actually works and observe admission constraints (PSA, image pull, securityContext) before committing to an escape path.",
      "leveraging": "create:pods -> get:serviceaccounts",
      "first_concrete_step": "Use wget with the SA token to POST a minimal pod manifest to https://10.96.0.1:443/api/v1/namespaces/stuck-lab/pods and inspect the response for admission denials.",
      "risk": "Pod Security Admission (restricted/baseline) may reject privileged/hostPath pods; no image registry reachable from cluster; RBAC may be namespace-scoped only."
    },
    {
      "id": "D2",
      "goal": "Harvest secrets reachable from a pod we control (mounted SA tokens, env-injected secrets, projected volumes).",
      "leveraging": "create:pods -> get:secrets",
      "first_concrete_step": "Create a pod that mounts the default SA token and any referenced secrets/configmaps, then read /var/run/secrets/kubernetes.io/serviceaccount and env from inside.",
      "risk": "Secrets may not be mountable without explicit RBAC on the pod's SA; PSA may block hostPath; image may not exist."
    },
    {
      "id": "D3",
      "goal": "Enumerate cluster topology and other workloads' data via pod-mounted configmaps/PVCs to find higher-value targets.",
      "leveraging": "create:pods -> get:configmaps / get:persistentvolumeclaims",
      "first_concrete_step": "Create a pod mounting candidate configmaps and PVCs (discovered via the pod's own API access) and dump their contents.",
      "risk": "PVCs may be ReadWriteOnce and already bound; configmaps may be empty; no direct list permission so discovery relies on pod-side API calls."
    },
    {
      "id": "D4",
      "goal": "Assess node-level escape feasibility (hostPath, privileged, nsenter) given we are root in a pod and have nsenter/unshare/chroot available.",
      "leveraging": "create:pods -> get:nodes",
      "first_concrete_step": "Create a pod with hostPath / and privileged:true (or hostPID) and test nsenter -t 1 -m to reach the host mount namespace.",
      "risk": "PSA restricted profile and/or admission webhooks will block privileged/hostPath; WSL2 kernel may restrict namespaces; node may be tainted."
    }
  ]
}

